// Import of required libraries
import { test, getBaseUrl, newSkyrampPlaywrightPage, expect } from '@skyramp/skyramp';
import { openVetList, toggleVetSpecialty } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(1994000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await openVetList(page);

    const vetRow = page.locator("#vets tbody tr").filter({ hasText: "James Carter" });
    const specialtyCell = vetRow.locator("td").nth(1);

    // The vet under test is seeded with zero specialties.
    await expect(vetRow).toHaveCount(1);
    await expect(specialtyCell).toHaveText("No specialties");

    await toggleVetSpecialty(page, "James Carter", "radiology");

    // The cell now renders the specialty inline; an exact text match proves the
    // "No specialties" placeholder is no longer rendered alongside it.
    await expect(specialtyCell).toHaveText("radiology");
    await expect(page.locator("#vets tbody tr")).toHaveCount(6);

    await toggleVetSpecialty(page, "James Carter", "radiology");

    // Removing the last specialty brings the empty-state placeholder back,
    // restoring the seeded state so this test is re-runnable.
    await expect(specialtyCell).toHaveText("No specialties");
    await expect(page.locator("#vets tbody tr")).toHaveCount(6);
});
